import json, sys, uuid, urllib.request, http.cookiejar
B = 'http://127.0.0.1:4345'
jar = http.cookiejar.CookieJar()
op = urllib.request.build_opener(urllib.request.HTTPCookieProcessor(jar))
def call(path, data=None, headers=None):
    h = {'Content-Type': 'application/json', 'Origin': B}
    h.update(headers or {})
    req = urllib.request.Request(B + path, data=json.dumps(data).encode() if data is not None else None, headers=h, method='POST' if data is not None else 'GET')
    try:
        with op.open(req) as r:
            return r.status, json.load(r)
    except urllib.error.HTTPError as e:
        return e.code, json.load(e)
st, s = call('/api/sessions', {'description': 'probe', 'conversation': []}, {'Idempotency-Key': str(uuid.uuid4())})
sid = s['id']
def turn(text, **kw):
    st, d = call(f'/api/sessions/{sid}/turns', {'text': text, 'clientTurnId': str(uuid.uuid4()), **kw})
    if st != 200:
        print('###', text, st, d); return
    print('###', repr(text), '->', d['outcome'], 'v', d['version'])
    for m in d['messages']:
        if m['role'] == 'tailor':
            print('   [%s] %s' % (m['status'], m['text']))
    print('   steps:', [(x['name'], x['status']) for x in d['steps']], 'exec:', d['execution'])
for t in sys.argv[1:]:
    turn(t)

